python3 -c "import re, pathlib
d = pathlib.Path('docs')
md = {p.stem for p in d.glob('weekly-????-W??.md')}
html = {p.stem for p in d.glob('weekly-????-W??.html')}
sm = {u.rsplit('/', 1)[-1][:-5] for u in re.findall(r'<loc>([^<]+)</loc>', d.joinpath('sitemap.xml').read_text()) if '/weekly-' in u}
print('md', len(md), 'html', len(html), 'sitemap', len(sm))
assert md == html == sm, (sorted(md - html), sorted(html - sm))"

python3 -c "import re, pathlib
d = pathlib.Path('docs')
mds = {p.name[:-3] for p in d.glob('????-??-??.md')}
html = {p.name[:-5] for p in d.glob('????-??-??.html')}
sm = {u.rsplit('/', 1)[-1][:-5] for u in re.findall(r'<loc>([^<]+)</loc>', d.joinpath('sitemap.xml').read_text()) if re.search(r'/\d{4}-\d{2}-\d{2}\.html$', u)}
assert mds == html == sm, ('no page', sorted(mds - html), 'not in sitemap', sorted(html - sm))
bad, titles = [], set()
for name in sorted(html):
    h = d.joinpath(name + '.html').read_text()
    t = re.search(r'<title>([^<]+)</title>', h).group(1)
    if t in titles: bad.append(name + ':dup-title')
    titles.add(t)
    if not re.search(r'name=\x22description\x22[^>]+content=\x22[^\x22]{20,}', h): bad.append(name + ':desc')
    if 'rel=\x22canonical\x22' not in h: bad.append(name + ':canonical')
    if 'property=\x22og:' not in h: bad.append(name + ':og')
    if 'application/ld+json' not in h: bad.append(name + ':ld')
print('pages', len(html), 'mds', len(mds), 'sitemap', len(sm), 'problems', bad[:3])
assert not bad"
